import argparse
import json
from pathlib import Path
import sys
import tempfile
from . import TeamPlanner

ACTIONS = {'member': 'add_member', 'activity': 'create_activity', 'enroll': 'enroll', 'enroll-batch': 'enroll_batch', 'preview-enroll': 'preview_enrollments', 'cancel': 'cancel_enrollments', 'transfer': 'transfer_enrollment', 'transfer-batch': 'transfer_enrollments', 'preview-transfer': 'preview_transfer_enrollments', 'split-activity': 'split_activity', 'reschedule': 'reschedule_activity', 'reschedule-batch': 'reschedule_activities', 'preview-reschedule': 'preview_reschedule_activities', 'roster': 'roster', 'list': 'activities', 'complete': 'record_completion', 'complete-batch': 'record_completions', 'correct-completions': 'correct_completions', 'completions': 'completions', 'merge': 'merge_member', 'merge-activities': 'merge_activities', 'schedule': 'member_schedule', 'enrollment-options': 'enrollment_options', 'training-progress': 'training_progress', 'training-requirements': 'training_requirements', 'training-validity': 'training_validity', 'training-timeline': 'training_validity_timeline', 'training-coverage': 'training_coverage', 'preview-absence-coverage': 'preview_absence_coverage', 'group-coverage': 'group_coverage', 'exclusive-group-coverage': 'exclusive_group_coverage', 'absence-start-options': 'absence_start_options', 'group-absence-start-options': 'group_absence_start_options', 'training-alerts': 'training_alerts', 'renewal-options': 'training_renewal_options', 'export-schedule': 'export_schedule'}

def samples(name):
    return json.loads((Path(__file__).resolve().parent.parent / "examples" / name).read_text(encoding="utf-8"))

def demo(app):
    for member in samples("members.json"):
        app.add_member(**member)
    app.create_activity(**samples("activity.json"))
    app.enroll(**samples("enrollment.json"))
    # 2026-10-15 的虚构安排：A-002 与 A-001 同日，由小陈和小周报满；
    # 小陈在 A-003 已登记完成，报名仍然保留，当天原本互为冲突。
    app.create_activity("A-002", "安全规范", "2026-10-15", 2)
    app.create_activity("A-003", "团队协作", "2026-10-15", 2)
    app.enroll("A-002", "M-001")
    app.enroll("A-002", "M-003")
    app.enroll("A-003", "M-001")
    app.record_completion("A-003", "M-001", "2026-10-15")
    # 一次取消两场，标识带首尾空白也会先去除；满员的 A-002 释放席位，
    # 返回顺序与输入一致，且各活动只移除小陈本人。
    cancelled = app.cancel_enrollments("M-001", [" A-002 ", "A-001"])
    if [a["activity_id"] for a in cancelled] != ["A-002", "A-001"]:
        raise ValueError("demo: cancelled activities must follow the input order")
    if cancelled[0]["participants"] != ["M-003"] or cancelled[1]["participants"] != []:
        raise ValueError("demo: only the cancelling member is removed")
    # 取消后小陈只剩已完成的 A-003，同日冲突随之消失。
    schedule = app.member_schedule("M-001")
    if [r["activity_id"] for r in schedule] != ["A-003"] or schedule[0]["conflict_activity_ids"] != []:
        raise ValueError("demo: same-day conflicts must disappear after cancellation")
    # 释放的席位立即可用：小林报进原本满员的 A-002，小陈重新报回 A-001。
    app.enroll("A-002", "M-002")
    app.enroll("A-001", "M-001")
    # 小陈在 A-003 已有本人完成记录：整次取消被拒绝，两边名单均不变，
    # 完成记录继续保留。
    try:
        app.cancel_enrollments("M-001", ["A-001", "A-003"])
    except ValueError:
        pass
    else:
        raise ValueError("demo: cancelling a completed activity must fail")
    if [m["member_id"] for m in app.roster("A-001")["members"]] != ["M-001"]:
        raise ValueError("demo: rosters must stay unchanged after a rejected cancellation")
    if [m["member_id"] for m in app.roster("A-003")["members"]] != ["M-001"]:
        raise ValueError("demo: the completed activity roster must stay unchanged")
    if [r["activity_id"] for r in app.completions("M-001")] != ["A-003"]:
        raise ValueError("demo: completion records must be kept")
    # 整组完成登记：2026-10-15 当天两场虚构培训（小陈的 A-001、小周的 A-002）
    # 一次性提交，允许跨活动、跨成员，标识带首尾空白会先去除；返回顺序与输入
    # 一致，字段与单条 complete 相同，两场都应登记成功。
    recorded = app.record_completions([
        {"activity_id": " A-001 ", "member_id": "M-001", "completed_on": "2026-10-15"},
        {"activity_id": "A-002", "member_id": " M-003 ", "completed_on": "2026-10-15"},
    ])
    if [r["activity_id"] for r in recorded] != ["A-001", "A-002"]:
        raise ValueError("demo: batch records must follow the input order")
    if recorded[0] != {"activity_id": "A-001", "member_id": "M-001", "completed_on": "2026-10-15", "title": "新成员产品介绍", "on": "2026-10-15"}:
        raise ValueError("demo: batch record fields must match the single complete result")
    # 末条失败（小陈在 A-003 已有完成记录）时整组拒绝：首条小林在 A-002 的
    # 新记录也不得写入，数据文件字节不变。
    before = app.path.read_bytes()
    try:
        app.record_completions([
            {"activity_id": "A-002", "member_id": "M-002", "completed_on": "2026-10-15"},
            {"activity_id": "A-003", "member_id": "M-001", "completed_on": "2026-10-15"},
        ])
    except ValueError:
        pass
    else:
        raise ValueError("demo: a batch with a failing last record must be rejected")
    if before != app.path.read_bytes():
        raise ValueError("demo: a rejected batch must leave data.json bytes unchanged")
    if app.completions("M-002") != []:
        raise ValueError("demo: no record from the rejected batch may survive")
    # 完成登记不取消报名：两场新完成的培训仍然占位、名单顺序不变。
    if [m["member_id"] for m in app.roster("A-001")["members"]] != ["M-001"]:
        raise ValueError("demo: completion keeps the enrollment")
    return app.roster("A-001")

def main(argv=None):
    parser = argparse.ArgumentParser(description="团队培训安排")
    parser.add_argument("--root", required=True, help="local data directory")
    parser.add_argument("action", choices=[*ACTIONS, "demo"])
    parser.add_argument("input", nargs="?", help="UTF-8 JSON object, or array of objects, containing API arguments")
    args = parser.parse_args(argv)
    try:
        if args.action == "demo":
            # Sample operations run in a fresh child directory and never overwrite user's data.
            Path(args.root).mkdir(parents=True, exist_ok=True)
            with tempfile.TemporaryDirectory(prefix="sample-", dir=args.root) as location:
                value = demo(TeamPlanner(location))
        else:
            payload = json.loads(Path(args.input).read_text(encoding="utf-8")) if args.input else {}
            app = TeamPlanner(args.root)
            method = getattr(app, ACTIONS[args.action])
            if isinstance(payload, list):
                value = []
                for row in payload:
                    if not isinstance(row, dict):
                        raise ValueError("each input must be an object")
                    value.append(method(**row))
            elif isinstance(payload, dict):
                value = method(**payload)
            else:
                raise ValueError("input must be an object or array")
        print(json.dumps(value, ensure_ascii=False, sort_keys=True))
        return 0
    except (ValueError, KeyError, TypeError, OSError) as error:
        print(json.dumps({"error": str(error)}, ensure_ascii=False), file=sys.stderr)
        return 2

if __name__ == "__main__":
    raise SystemExit(main())

def group_coverage(self, groups, from_on, to_on, absences=None, member_ids=None):
    # Read-only per-group absence preview over preview_absence_coverage:
    # the qualified and absent members per day are computed exactly as
    # there, but every group is judged on its own — a member enters one
    # group's qualified list as soon as that group is valid for them that
    # day, without needing the other groups to be valid, and the same
    # member may count in several groups at once. The headcount
    # requirement moves from the top level into each group. The groups and
    # absences exist only for this call: nothing is ever stored, and
    # enrollments, completion records and profiles are used as they are,
    # never reconstructed historically; the current date is never
    # consulted.
    if not isinstance(groups, list) or not groups:
        raise ValueError("groups must be a nonempty array")
    selected_groups = []
    seen_groups = set()
    seen_activities = set()
    for item in groups:
        if not isinstance(item, dict) or set(item) != {"group_id", "activity_ids", "valid_days", "minimum_count"}:
            raise ValueError("each group must contain only group_id, activity_ids, valid_days and minimum_count")
        group_id = text(item["group_id"], "group_id")
        if group_id in seen_groups:
            raise ValueError("group_ids must not contain duplicates")
        seen_groups.add(group_id)
        valid_days = positive(item["valid_days"], "valid_days")
        # The per-group headcount is a non-boolean positive integer; it may
        # exceed the number of selected members.
        minimum_count = positive(item["minimum_count"], "minimum_count")
        activity_ids = item["activity_ids"]
        if not isinstance(activity_ids, list) or not activity_ids:
            raise ValueError("activity_ids must be a nonempty array")
        group_activities = []
        for activity_id in activity_ids:
            activity_id = text(activity_id, "activity_id")
            # As in preview_absence_coverage, an activity belongs to
            # exactly one group and may not repeat inside it.
            if activity_id in seen_activities:
                raise ValueError("activity_ids must not repeat within or across groups")
            seen_activities.add(activity_id)
            group_activities.append(activity_id)
        selected_groups.append((group_id, group_activities, valid_days, minimum_count))
    from_on = day(from_on, "from_on")
    to_on = day(to_on, "to_on")
    if from_on > to_on:
        raise ValueError("from_on must be on or before to_on")
    # The absence list is required, exactly as in preview_absence_coverage:
    # null (or a missing argument) is rejected, an empty array is allowed.
    if absences is None or not isinstance(absences, list):
        raise ValueError("absences must be an array")
    absence_entries = []
    for item in absences:
        if not isinstance(item, dict) or set(item) != {"member_id", "from_on", "to_on"}:
            raise ValueError("each absence must contain only member_id, from_on and to_on")
        absence_member_id = text(item["member_id"], "member_id")
        absence_from = day(item["from_on"], "from_on")
        absence_to = day(item["to_on"], "to_on")
        # Whole-day closed intervals; a reversed range is rejected.
        if absence_from > absence_to:
            raise ValueError("from_on must be on or before to_on")
        absence_entries.append((absence_member_id, absence_from, absence_to))
    # member_ids follows preview_absence_coverage exactly: omitted or null
    # means every member, an empty array means no members at all.
    if member_ids is None:
        selected_member_ids = None
    elif not isinstance(member_ids, list):
        raise ValueError("member_ids must be an array or null")
    else:
        selected_member_ids = []
        seen_members = set()
        for member_id in member_ids:
            member_id = text(member_id, "member_id")
            if member_id in seen_members:
                raise ValueError("member_ids must not contain duplicates")
            seen_members.add(member_id)
            selected_member_ids.append(member_id)
    data = self._read()
    members = data.get("members", {})
    activities = data.get("activities", {})
    completions = data.get("completions", {})
    # Every reference is validated even when nobody is selected and every
    # absence falls outside the range.
    for _, activity_ids, _, _ in selected_groups:
        for activity_id in activity_ids:
            if activities.get(activity_id) is None:
                raise ValueError("unknown activity")
    if selected_member_ids is None:
        # Everyone, by ascending identifier.
        ordered_member_ids = sorted(members)
    else:
        for member_id in selected_member_ids:
            if member_id not in members:
                raise ValueError("unknown member")
        ordered_member_ids = selected_member_ids
    for absence_member_id, _, _ in absence_entries:
        if absence_member_id not in members:
            raise ValueError("unknown member")
    start = date.fromisoformat(from_on)
    end = date.fromisoformat(to_on)

    def valid_intervals(member_id, activity_ids, valid_days):
        # The eligible records are exactly preview_absence_coverage's,
        # which are exactly training_validity's: a stored completion only
        # exists for enrolled members, and a missing record is the same as
        # no record.
        records_by_date = {}
        for activity_id in activity_ids:
            activity = activities[activity_id]
            if member_id not in activity.get("participants", []):
                continue
            completed_on = completions.get(activity_id, {}).get(member_id)
            if completed_on is not None:
                records_by_date.setdefault(date.fromisoformat(completed_on), []).append(
                    (activity["on"], activity_id)
                )
        takeovers = sorted(records_by_date)
        intervals = []
        for index, completed in enumerate(takeovers):
            segment_end = takeovers[index + 1] - timedelta(days=1) if index + 1 < len(takeovers) else date.max
            # The expiry is the completion day plus valid_days calendar
            # days; the expiry day itself is expired. An expiry past
            # date.max is beyond every possible range end, so the record
            # stays valid through the range instead of raising.
            try:
                expires = completed + timedelta(days=valid_days)
            except OverflowError:
                expires = None
            valid_end = segment_end if expires is None else min(segment_end, expires - timedelta(days=1))
            frm, to = max(completed, start), min(valid_end, end)
            if frm <= to:
                intervals.append((frm, to))
        return intervals

    # Per member and group, the days on which that group alone is valid;
    # the groups are never intersected with each other.
    qualified = [
        [valid_intervals(member_id, activity_ids, valid_days) for _, activity_ids, valid_days, _ in selected_groups]
        for member_id in ordered_member_ids
    ]

    # Per selected member, the absence days inside the range, exactly as in
    # preview_absence_coverage: repeated, overlapping or adjacent requests
    # are a union of days and never deduct the member twice; absences of
    # members not selected and days outside the range never change the
    # counts.
    absent = {member_id: [] for member_id in ordered_member_ids}
    for absence_member_id, absence_from, absence_to in absence_entries:
        if absence_member_id not in absent:
            continue
        frm = max(date.fromisoformat(absence_from), start)
        to = min(date.fromisoformat(absence_to), end)
        if frm <= to:
            absent[absence_member_id].append((frm, to))

    # Sweep the range: any group's qualified set or the absent set can only
    # change where one of the intervals starts or ends, so the days between
    # consecutive edges share every set. Every edge lies inside the range,
    # so no date overflows.
    edges = set()
    for per_group in qualified:
        for intervals in per_group:
            for frm, to in intervals:
                if frm > start:
                    edges.add(frm)
                if to < end:
                    edges.add(to + timedelta(days=1))
    for intervals in absent.values():
        for frm, to in intervals:
            if frm > start:
                edges.add(frm)
            if to < end:
                edges.add(to + timedelta(days=1))
    boundaries = [start] + sorted(edges)
    periods = []
    for index, frm in enumerate(boundaries):
        to = boundaries[index + 1] - timedelta(days=1) if index + 1 < len(boundaries) else end
        key = tuple(
            (
                tuple(
                    member_id
                    for member_id, member_qualified in zip(ordered_member_ids, qualified)
                    if any(f <= frm <= t for f, t in member_qualified[group_index])
                ),
                tuple(
                    member_id
                    for member_id, member_qualified in zip(ordered_member_ids, qualified)
                    if any(f <= frm <= t for f, t in member_qualified[group_index])
                    and any(f <= frm <= t for f, t in absent[member_id])
                ),
            )
            for group_index in range(len(selected_groups))
        )
        if periods and periods[-1][2] == key:
            # Same qualified and absent members in every group on the
            # following days extend the open period instead of starting a
            # new one; a same-size swap of people still splits, and a mere
            # change of the underlying completion record never does.
            periods[-1][1] = to
        else:
            periods.append([frm, to, key])
    return {
        "from_on": from_on,
        "to_on": to_on,
        "periods": [
            {
                "from_on": frm.isoformat(),
                "to_on": to.isoformat(),
                "groups": [
                    {
                        "group_id": group_id,
                        "minimum_count": minimum_count,
                        "valid_member_ids": list(ids),
                        "valid_count": len(ids),
                        "absent_member_ids": list(away),
                        "available_member_ids": [member_id for member_id in ids if member_id not in away],
                        "available_count": len(ids) - len(away),
                        "shortage_count": max(0, minimum_count - (len(ids) - len(away))),
                    }
                    for (group_id, _, _, minimum_count), (ids, away) in zip(selected_groups, key)
                ],
                # Only a period where no group is short meets the
                # requirements.
                "meets_requirements": all(
                    len(ids) - len(away) >= minimum_count
                    for (_, _, _, minimum_count), (ids, away) in zip(selected_groups, key)
                ),
            }
            for frm, to, key in periods
        ],
    }

def exclusive_group_coverage(self, groups, from_on, to_on, absences=None, member_ids=None):
    # Read-only shared-pool staffing check over group_coverage: the
    # inputs, validation, per-group lists and figures, and the period
    # splitting and merging are exactly group_coverage's, but on top of
    # that each period is also judged as one shared staffing pool for the
    # day — the same member fills at most one group's position per day
    # and each group fills at most its own minimum_count positions. The
    # assignment is only used for the headcount and is never stored; the
    # groups and absences exist only for this call, nothing is ever
    # written, and the current date is never consulted.
    result = self.group_coverage(groups, from_on, to_on, absences, member_ids)
    for period in result["periods"]:
        per_group = period["groups"]
        required = sum(group["minimum_count"] for group in per_group)
        # The largest number of simultaneously fillable positions is a
        # bipartite matching between the available members (each usable
        # in at most one group) and the group positions (each group
        # capped at its own requirement), found by augmenting paths.
        # Only the size matters; the assignment itself is discarded.
        available = [group["available_member_ids"] for group in per_group]
        assignment = {}

        def augment(group_index, seen):
            for member_id in available[group_index]:
                if member_id in seen:
                    continue
                seen.add(member_id)
                if member_id not in assignment or augment(assignment[member_id], seen):
                    assignment[member_id] = group_index
                    return True
            return False

        filled = 0
        for group_index, group in enumerate(per_group):
            for _ in range(group["minimum_count"]):
                if not augment(group_index, set()):
                    break
                filled += 1
        period["required_count"] = required
        period["filled_count"] = filled
        period["shortage_count"] = required - filled
        # Only a period whose positions can all be filled at once meets
        # the requirements; every group individually having enough
        # available members is not sufficient on its own.
        period["meets_requirements"] = filled == required
    return result

